25	import java.util.List;
26	import java.util.Locale;
27	import java.util.Map;
28	import java.util.regex.Pattern;
29	
30	import org.slf4j.Logger;
31	import org.slf4j.LoggerFactory;
32	import org.springframework.http.HttpHeaders;
33	import org.springframework.http.HttpStatus;
34	import org.springframework.http.ResponseEntity;
35	import org.springframework.samples.petclinic.mapper.OwnerMapper;
36	import org.springframework.samples.petclinic.mapper.PetMapper;
37	import org.springframework.samples.petclinic.mapper.VisitMapper;
38	import org.springframework.samples.petclinic.model.Owner;
39	import org.springframework.samples.petclinic.model.Pet;
40	import org.springframework.samples.petclinic.model.Visit;
41	import org.springframework.samples.petclinic.rest.advice.CityAtCapacityException;
42	import org.springframework.samples.petclinic.rest.advice.DailyOwnerLimitException;
43	import org.springframework.samples.petclinic.rest.advice.DuplicateIdentityException;
44	import org.springframework.samples.petclinic.rest.advice.InvalidEmailException;
45	import org.springframework.samples.petclinic.rest.advice.InvalidPostcodeException;
46	import org.springframework.samples.petclinic.rest.advice.InvalidTelephoneException;
47	import org.springframework.samples.petclinic.rest.advice.MissingOwnerFieldsException;
48	import org.springframework.samples.petclinic.rest.api.OwnersApi;
49	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
50	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
51	import org.springframework.samples.petclinic.rest.dto.PetDto;
52	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
53	import org.springframework.samples.petclinic.rest.dto.VisitDto;
54	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
55	import org.springframework.samples.petclinic.service.ClinicService;
56	import org.springframework.security.access.prepost.PreAuthorize;
57	import org.springframework.web.bind.annotation.CrossOrigin;
58	import org.springframework.web.bind.annotation.RequestMapping;
59	import org.springframework.web.bind.annotation.RestController;
60	import org.springframework.web.util.UriComponentsBuilder;
61	
62	import jakarta.transaction.Transactional;
63	
64	/**
65	 * @author Vitaliy Fedoriv
66	 */
67	
68	@RestController
69	@CrossOrigin(exposedHeaders = "errors, content-type")
70	@RequestMapping("/api")
71	public class OwnerRestControllerV1 implements OwnersApi {
72	
73	    /**
74	     * Matches a syntactically valid email: a non-empty local part and domain separated by a single
75	     * '@', with at least one dot-separated label in the domain and no whitespace anywhere.
76	     */
77	    private static final Pattern EMAIL_PATTERN =
78	        Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
79	
80	    /**
81	     * Dedicated audit logger. On a successful owner create an audit line is emitted carrying the
82	     * new owner's id, customerCode, registrationDate and membershipLevel.
83	     */
84	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
85	
86	    /**
87	     * Common street-type abbreviations expanded during address normalization, keyed by the
88	     * upper-cased abbreviation.
89	     */
90	    private static final Map<String, String> ADDRESS_ABBREVIATIONS =
91	        Map.of("ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
92	
93	    /**
94	     * Maximum number of owners a single city may contain. A create is rejected once the owner's
95	     * city already holds this many owners.
96	     */
97	    private static final int CITY_CAPACITY = 50;
98	
99	    /**
100	     * Maximum number of owners that may be created on a single day. A create is rejected once this
101	     * many owners already carry the current day as their {@code registrationDate}.
102	     */
103	    private static final int DAILY_OWNER_LIMIT = 100;
104	
105	    private final ClinicService clinicService;
106	
107	    private final OwnerMapper ownerMapper;
108	
109	    private final PetMapper petMapper;
110	
111	    private final VisitMapper visitMapper;
112	
113	    public OwnerRestControllerV1(ClinicService clinicService,
114	                                 OwnerMapper ownerMapper,
115	                                 PetMapper petMapper,
116	                                 VisitMapper visitMapper) {
117	        this.clinicService = clinicService;
118	        this.ownerMapper = ownerMapper;
119	        this.petMapper = petMapper;
120	        this.visitMapper = visitMapper;
121	    }
122	
123	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
124	    @Override
125	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
126	        Collection<Owner> owners;
127	        if (lastName != null) {
128	            owners = this.clinicService.findOwnerByLastName(lastName);
129	        } else {
130	            owners = this.clinicService.findAllOwners();
131	        }
132	        if (owners.isEmpty()) {
133	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
134	        }
135	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
136	    }
137	
138	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
139	    @Override
140	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
141	        Owner owner = this.clinicService.findOwnerById(ownerId);
142	        if (owner == null) {
143	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
144	        }
145	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
146	    }
147	
148	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
149	    @Override
150	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
151	        validateRequiredFields(ownerFieldsDto);
152	        validatePostcode(ownerFieldsDto.getPostcode(), ownerFieldsDto.getCity());
153	        HttpHeaders headers = new HttpHeaders();
154	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
155	        owner.setAddress(normalizeAddress(ownerFieldsDto.getAddress()));
156	        LocalDate effectiveDate = owner.getRegistrationDate() == null
157	            ? LocalDate.now()
158	            : owner.getRegistrationDate();
159	        owner.setRegistrationDate(toBusinessDay(effectiveDate));
160	        rejectWhenDailyLimitReached(owner.getRegistrationDate());
161	        rejectWhenCityAtCapacity(owner.getCity());
162	        applyHousehold(owner);
163	        owner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
164	        owner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
165	        rejectDuplicateIdentity(owner);
166	        owner.setCustomerCode(customerCode(owner));
167	        owner.setMembershipNumber(membershipNumber(owner.getCustomerCode(), owner.getRegistrationDate()));
168	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
169	        this.clinicService.saveOwner(owner);
170	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
171	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={}",
172	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
173	            ownerDto.getMembershipLevel());
174	        headers.setLocation(UriComponentsBuilder.newInstance()
175	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
176	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
177	    }
178	
179	    /**
180	     * Builds the owner's customer code, formatted {@code <REGION>-<HASH8>} where REGION is the region
181	     * code derived from the owner's postcode (falling back to the city-to-region table, then
182	     * {@code UNKNOWN}) and HASH8 is the first 8 upper-cased hex characters of the SHA-256 of the
183	     * owner's normalized telephone concatenated with its last name (e.g. {@code NSW-1A2B3C4D}). The
184	     * code is a pure function of the owner's region and identity, carrying no sequence number.
185	     *
186	     * @param owner the owner being created, with its normalized telephone already applied
187	     * @return the assigned customer code
188	     */
189	    private String customerCode(Owner owner) {
190	        return regionCode(owner) + "-" + identityHash8(owner.getTelephone(), owner.getLastName());
191	    }
192	
193	    /**
194	     * Derives the region code embedded in an owner's customer code, preferring the postcode: a
195	     * 4-digit postcode falling in a known region's range (NSW 2000-2099, VIC 3000-3099,
196	     * QLD 4000-4099) yields that region. Otherwise the city-to-region table (Sydney->NSW,
197	     * Melbourne->VIC, Brisbane->QLD) is consulted, returning {@code UNKNOWN} when neither the
198	     * postcode nor the city identifies a region.
199	     *
200	     * @param owner the owner being created
201	     * @return the derived region code, never {@code null}
202	     */
203	    private String regionCode(Owner owner) {
204	        String fromPostcode = regionFromPostcode(owner.getPostcode());
205	        if (fromPostcode != null) {
206	            return fromPostcode;
207	        }
208	        String fromCity = region(owner.getCity());
209	        return fromCity == null ? "UNKNOWN" : fromCity;
210	    }
211	
212	    /**
213	     * Resolves the region whose postcode range contains the given postcode, or {@code null} when the
214	     * postcode is absent, not 4 digits, or in no known range.
215	     *
216	     * @param postcode the owner's postcode, may be {@code null}
217	     * @return the region code, or {@code null} when no known range contains the postcode
218	     */
219	    private String regionFromPostcode(String postcode) {
220	        if (postcode == null || !postcode.matches("[0-9]{4}")) {
221	            return null;
222	        }
223	        int value = Integer.parseInt(postcode);
224	        for (Map.Entry<String, int[]> entry : REGION_POSTCODE_RANGES.entrySet()) {
225	            int[] range = entry.getValue();
226	            if (value >= range[0] && value <= range[1]) {
227	                return entry.getKey();
228	            }
229	        }
230	        return null;
231	    }
232	
233	    /**
234	     * Computes the identity hash embedded in an owner's customer code: the first 8 upper-cased hex
235	     * characters of the SHA-256 of the owner's normalized telephone concatenated with its last name.
236	     *
237	     * @param telephone the owner's normalized (E.164) telephone
238	     * @param lastName  the owner's last name
239	     * @return the 8-character upper-cased hex hash
240	     */
241	    private String identityHash8(String telephone, String lastName) {
242	        String input = (telephone == null ? "" : telephone) + (lastName == null ? "" : lastName);
243	        try {
244	            byte[] digest = MessageDigest.getInstance("SHA-256")
245	                .digest(input.getBytes(StandardCharsets.UTF_8));
246	            StringBuilder hex = new StringBuilder(digest.length * 2);
247	            for (byte b : digest) {
248	                hex.append(String.format("%02x", b));
249	            }
250	            return hex.substring(0, 8).toUpperCase(Locale.ROOT);
251	        } catch (NoSuchAlgorithmException ex) {
252	            throw new IllegalStateException("SHA-256 not available", ex);
253	        }
254	    }
255	
256	    /**
257	     * Builds the owner's membership number, formatted {@code <customerCode>-M<YY>} where YY is the
258	     * last two digits of the registrationDate year, zero-padded (e.g. {@code NSW-1A2B3C4D-M26}).
259	     *
260	     * @param customerCode     the owner's assigned customer code
261	     * @param registrationDate the owner's registration date
262	     * @return the assigned membership number
263	     */
264	    private String membershipNumber(String customerCode, LocalDate registrationDate) {
265	        return String.format("%s-M%02d", customerCode, registrationDate.getYear() % 100);
266	    }
267	
268	    /**
269	     * Counts the existing owners that already share the given firstName and lastName, compared
270	     * case-insensitively. Evaluated before the owner being created is saved, so it reflects only
271	     * the owners that pre-existed this create.
272	     *
273	     * @param firstName the new owner's first name
274	     * @param lastName  the new owner's last name
275	     * @return the number of existing namesakes
276	     */
277	    private int countNamesakes(String firstName, String lastName) {
278	        return (int) this.clinicService.findAllOwners().stream()
279	            .filter(existing -> equalsIgnoreCase(existing.getFirstName(), firstName)
280	                && equalsIgnoreCase(existing.getLastName(), lastName))
281	            .count();
282	    }
283	
284	    /**
285	     * Rejects creating an owner when their city already contains {@link #CITY_CAPACITY} or more
286	     * owners. Existing owners are counted case-insensitively by city, matching how the per-city
287	     * customer-code sequence is derived.
288	     *
289	     * @param city the new owner's city
290	     * @throws CityAtCapacityException if the city already holds {@link #CITY_CAPACITY} owners
291	     */
292	    private void rejectWhenCityAtCapacity(String city) {
293	        long count = this.clinicService.findAllOwners().stream()
294	            .filter(existing -> equalsIgnoreCase(existing.getCity(), city))
295	            .count();
296	        if (count >= CITY_CAPACITY) {
297	            throw new CityAtCapacityException(city);
298	        }
299	    }
300	
301	    /**
302	     * Rejects creating an owner once {@link #DAILY_OWNER_LIMIT} or more owners already carry the
303	     * given business day as their {@code registrationDate}. The day is the owner's adjusted,
304	     * business-day registration date, so the limit is enforced per business day and weekend
305	     * requests count against the Monday they roll forward to.
306	     *
307	     * @param registrationDate the owner's adjusted (business-day) registration date
308	     * @throws DailyOwnerLimitException if {@link #DAILY_OWNER_LIMIT} owners already carry that
309	     *                                  registration date
310	     */
311	    private void rejectWhenDailyLimitReached(LocalDate registrationDate) {
312	        long count = this.clinicService.findAllOwners().stream()
313	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
314	            .count();
315	        if (count >= DAILY_OWNER_LIMIT) {
316	            throw new DailyOwnerLimitException(registrationDate);
317	        }
318	    }
319	
320	    /**
321	     * Rolls a registration date forward onto a business day: when it falls on a Saturday or Sunday
322	     * it advances to the following Monday, otherwise it is returned unchanged. Applied to the
323	     * effective registration date (whether supplied in the request or defaulted to the server date)
324	     * so a weekend value never persists as an owner's {@code registrationDate}.
325	     *
326	     * @param date the effective registration date
327	     * @return the same date when it is a weekday, otherwise the next Monday
328	     */
329	    private LocalDate toBusinessDay(LocalDate date) {
330	        return switch (date.getDayOfWeek()) {
331	            case SATURDAY -> date.plusDays(2);
332	            case SUNDAY -> date.plusDays(1);
333	            default -> date;
334	        };
335	    }
336	
337	    private boolean equalsIgnoreCase(String a, String b) {
338	        return a == null ? b == null : a.equalsIgnoreCase(b);
339	    }
340	
341	    /**
342	     * Rejects an owner whose required fields are missing or blank. Collects the names of every
343	     * offending field so the client learns about all of them at once.
344	     *
345	     * @param ownerFieldsDto the submitted owner fields
346	     * @throws MissingOwnerFieldsException if firstName, lastName, address, city or telephone is
347	     *                                     missing or blank
348	     */
349	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
350	        List<String> errors = new ArrayList<>();
351	        if (isBlank(ownerFieldsDto.getFirstName())) {
352	            errors.add("firstName");
353	        }
354	        if (isBlank(ownerFieldsDto.getLastName())) {
355	            errors.add("lastName");
356	        }
357	        if (isBlank(normalizeAddress(ownerFieldsDto.getAddress()))) {
358	            errors.add("address");
359	        }
360	        if (isBlank(ownerFieldsDto.getCity())) {
361	            errors.add("city");
362	        }
363	        if (isBlank(ownerFieldsDto.getTelephone())) {
364	            errors.add("telephone");
365	        }
366	        if (!errors.isEmpty()) {
367	            throw new MissingOwnerFieldsException(errors);
368	        }
369	    }
370	
371	    private boolean isBlank(String value) {
372	        return value == null || value.isBlank();
373	    }
374	
375	    /**
376	     * The fixed inclusive 4-digit postcode range allowed for each region, keyed by region code
377	     * (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099).
378	     */
379	    private static final Map<String, int[]> REGION_POSTCODE_RANGES = Map.of(
380	        "NSW", new int[] {2000, 2099},
381	        "VIC", new int[] {3000, 3099},
382	        "QLD", new int[] {4000, 4099});
383	
384	    /**
385	     * Validates an owner's postcode, but only when one is supplied. A {@code null} or blank postcode
386	     * is optional and accepted, keeping the create contract backward-compatible. When present the
387	     * value must be 4 digits and, when the owner's city has a known region (Sydney->NSW,
388	     * Melbourne->VIC, Brisbane->QLD), must fall within that region's inclusive range (NSW 2000-2099,
389	     * VIC 3000-3099, QLD 4000-4099). A city with no known region accepts any 4-digit postcode.
390	     *
391	     * @param postcode the raw postcode value as submitted, may be {@code null}
392	     * @param city     the owner's city, used to resolve the region whose range applies
393	     * @throws InvalidPostcodeException if a supplied postcode is not 4 digits or is out of range for
394	     *                                  the city's region
395	     */
396	    private void validatePostcode(String postcode, String city) {
397	        if (isBlank(postcode)) {
398	            return;
399	        }
400	        if (!postcode.matches("[0-9]{4}")) {
401	            throw new InvalidPostcodeException(postcode, city);
402	        }
403	        String region = region(city);
404	        int[] range = region == null ? null : REGION_POSTCODE_RANGES.get(region);
405	        if (range != null) {
406	            int value = Integer.parseInt(postcode);
407	            if (value < range[0] || value > range[1]) {
408	                throw new InvalidPostcodeException(postcode, city);
409	            }
410	        }
411	    }
412	
413	    /**
414	     * Derives an owner's region from its city using the fixed city-to-region table (Sydney->NSW,
415	     * Melbourne->VIC, Brisbane->QLD), returning {@code null} when the city is not in the table.
416	     *
417	     * @param city the owner's city
418	     * @return the region code, or {@code null} when the city has no known region
419	     */
420	    private String region(String city) {
421	        if (city == null) {
422	            return null;
423	        }
424	        return switch (city) {
425	            case "Sydney" -> "NSW";
426	            case "Melbourne" -> "VIC";
427	            case "Brisbane" -> "QLD";
428	            default -> null;
429	        };
430	    }
431	
432	    /**
433	     * The number of national (subscriber) digits an E.164 number must carry for a given country
434	     * calling code, keyed by that code (without the leading '+'). Australia ('+61') requires 9
435	     * national digits and the North American Numbering Plan ('+1') requires 10.
436	     */
437	    private static final Map<String, Integer> NATIONAL_NUMBER_LENGTHS =
438	        Map.of("61", 9, "1", 10);
439	
440	    /**
441	     * Normalizes a submitted telephone into E.164 form. Spaces, dashes and brackets are stripped.
442	     * A leading '+' with its country code is kept; otherwise the country code '+61' is assumed and
443	     * a single leading '0' is dropped from the national digits. The resulting value must be a '+'
444	     * followed by 8 to 15 digits, and its national-number length must match the one required by its
445	     * country calling code ('+61' requires 9 national digits, '+1' requires 10).
446	     *
447	     * @param telephone the raw telephone value as submitted
448	     * @return the E.164 normalized telephone (e.g. {@code +61412345678})
449	     * @throws InvalidTelephoneException if the value cannot form a valid E.164 number, or its
450	     *                                   national-number length is wrong for its country code
451	     */
452	    private String normalizeTelephone(String telephone) {
453	        String cleaned = telephone == null ? "" : telephone.replaceAll("[\\s\\-()]", "");
454	        String nationalSignificantNumber;
455	        if (cleaned.startsWith("+")) {
456	            nationalSignificantNumber = cleaned.substring(1);
457	        } else {
458	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
459	            nationalSignificantNumber = "61" + national;
460	        }
461	        if (!nationalSignificantNumber.matches("[0-9]{8,15}")) {
462	            throw new InvalidTelephoneException(telephone);
463	        }
464	        validateNationalNumberLength(nationalSignificantNumber, telephone);
465	        return "+" + nationalSignificantNumber;
466	    }
467	
468	    /**
469	     * Validates the national-number length of an E.164 number against its country calling code. The
470	     * significant number is a country code immediately followed by the national digits; for each
471	     * known code in {@link #NATIONAL_NUMBER_LENGTHS} the remaining national digits must number
472	     * exactly the required amount ('+61' requires 9, '+1' requires 10). Codes with no known rule are
473	     * left unchecked.
474	     *
475	     * @param nationalSignificantNumber the E.164 digits following the '+' (country code + national)
476	     * @param rejectedValue             the raw telephone value, reported on rejection
477	     * @throws InvalidTelephoneException if the national-number length is wrong for the country code
478	     */
479	    private void validateNationalNumberLength(String nationalSignificantNumber, String rejectedValue) {
480	        for (Map.Entry<String, Integer> rule : NATIONAL_NUMBER_LENGTHS.entrySet()) {
481	            String countryCode = rule.getKey();
482	            if (nationalSignificantNumber.startsWith(countryCode)) {
483	                int nationalDigits = nationalSignificantNumber.length() - countryCode.length();
484	                if (nationalDigits != rule.getValue()) {
485	                    throw new InvalidTelephoneException(rejectedValue);
486	                }
487	                return;
488	            }
489	        }
490	    }
491	
492	    /**
493	     * Normalizes a submitted email. An owner may omit the email entirely (a {@code null} or blank
494	     * value is treated as absent and returns {@code null}); when present the value must be a
495	     * syntactically valid address, and is stored and returned lower-cased.
496	     *
497	     * @param email the raw email value as submitted, may be {@code null}
498	     * @return the lower-cased email, or {@code null} when none was supplied
499	     * @throws InvalidEmailException if a non-blank value is not a syntactically valid address
500	     */
501	    private String normalizeEmail(String email) {
502	        if (email == null || email.isBlank()) {
503	            return null;
504	        }
505	        String normalized = email.trim().toLowerCase();
506	        if (!EMAIL_PATTERN.matcher(normalized).matches()) {
507	            throw new InvalidEmailException(email);
508	        }
509	        return normalized;
510	    }
511	
512	    /**
513	     * The single, consolidated duplicate check. Rejects the owner being created when its whole
514	     * {@link #identityKey(Owner) identityKey} exactly equals that of an existing owner. Because the
515	     * key is the normalized telephone, email and householdId joined together, this one check
516	     * subsumes the former separate telephone, email and household duplicate rules: only an exact
517	     * full-key match counts as a duplicate, so two members of the same household (same householdId)
518	     * with different telephones have different keys and are both allowed.
519	     *
520	     * @param owner the owner being created, with its normalized telephone, email and householdId
521	     *              already applied
522	     * @throws DuplicateIdentityException if another owner already has the same identityKey
523	     */
524	    private void rejectDuplicateIdentity(Owner owner) {
525	        String identityKey = identityKey(owner);
526	        boolean inUse = this.clinicService.findAllOwners().stream()
527	            .map(this::identityKey)
528	            .anyMatch(identityKey::equals);
529	        if (inUse) {
530	            throw new DuplicateIdentityException(identityKey);
531	        }
532	    }
533	
534	    /**
535	     * Derives an owner's {@code identityKey}: {@code normalizedTelephone + '|' + (email or empty) +
536	     * '|' + householdId}. A {@code null} email or householdId contributes an empty segment. Every
537	     * duplicate decision is made by comparing whole identityKeys.
538	     *
539	     * @param owner the owner whose identityKey to derive
540	     * @return the derived identityKey
541	     */
542	    private String identityKey(Owner owner) {
543	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
544	        String email = owner.getEmail() == null ? "" : owner.getEmail();
545	        String householdId = owner.getHouseholdId() == null ? "" : owner.getHouseholdId();
546	        return telephone + "|" + email + "|" + householdId;
547	    }
548	
549	    /**
550	     * Applies the household rule to an owner being created. An owner belongs to the same household
551	     * as an existing owner when their lastName and address both match (compared case-insensitively
552	     * with runs of whitespace collapsed to a single space).
553	     *
554	     * <p>When no such existing owner exists there is nothing to do. Otherwise the new owner and
555	     * every existing owner in the household are assigned the same stable
556	     * {@link #householdId(String, String) householdId}. The household itself is no longer a
557	     * rejection: duplicate detection is now decided solely by the whole {@code identityKey}, of
558	     * which the householdId is one segment, so two members of the same household with different
559	     * telephones have different keys and are both allowed.
560	     *
561	     * @param owner the owner being created
562	     */
563	    private void applyHousehold(Owner owner) {
564	        String lastNameKey = toHouseholdKey(owner.getLastName());
565	        String addressKey = toHouseholdKey(owner.getAddress());
566	        List<Owner> household = this.clinicService.findAllOwners().stream()
567	            .filter(existing -> toHouseholdKey(existing.getLastName()).equals(lastNameKey)
568	                && toHouseholdKey(existing.getAddress()).equals(addressKey))
569	            .toList();
570	        if (household.isEmpty()) {
571	            return;
572	        }
573	        String householdId = householdId(lastNameKey, addressKey);
574	        owner.setHouseholdId(householdId);
575	        for (Owner existing : household) {
576	            if (!householdId.equals(existing.getHouseholdId())) {
577	                existing.setHouseholdId(householdId);
578	                this.clinicService.saveOwner(existing);
579	            }
580	        }
581	    }
582	
583	    /**
584	     * Derives the stable, shared household identifier for a household, formatted {@code HH-<HEX12>}
585	     * where HEX12 is the first 12 upper-cased hex characters of the SHA-256 of the normalized
586	     * lastName and address keys. Being a pure function of the household, every owner in it derives
587	     * the same value regardless of creation order.
588	     *
589	     * @param lastNameKey the normalized household lastName key
590	     * @param addressKey  the normalized household address key
591	     * @return the household identifier
592	     */
593	    private String householdId(String lastNameKey, String addressKey) {
594	        try {
595	            byte[] digest = MessageDigest.getInstance("SHA-256")
596	                .digest((lastNameKey + "|" + addressKey).getBytes(StandardCharsets.UTF_8));
597	            StringBuilder hex = new StringBuilder(digest.length * 2);
598	            for (byte b : digest) {
599	                hex.append(String.format("%02x", b));
600	            }
601	            return "HH-" + hex.substring(0, 12).toUpperCase(Locale.ROOT);
602	        } catch (NoSuchAlgorithmException ex) {
603	            throw new IllegalStateException("SHA-256 not available", ex);
604	        }
605	    }
606	
607	    /**
608	     * Normalizes a lastName or address for household comparison: leading and trailing whitespace is
609	     * trimmed, internal runs of whitespace are collapsed to a single space, and the value is
610	     * lower-cased so the comparison is case-insensitive. A {@code null} value normalizes to an empty
611	     * string.
612	     */
613	    private String toHouseholdKey(String value) {
614	        if (value == null) {
615	            return "";
616	        }
617	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
618	    }
619	
620	    /**
621	     * Normalizes a submitted address into the canonical form stored and returned for an owner:
622	     * leading and trailing whitespace is trimmed, internal runs of whitespace are collapsed to a
623	     * single space, the value is upper-cased, and common street-type abbreviations are expanded on a
624	     * whole-word basis ({@code ST->STREET}, {@code RD->ROAD}, {@code AVE->AVENUE}). A {@code null}
625	     * value, or one that is blank once trimmed, normalizes to an empty string.
626	     *
627	     * @param address the raw address value as submitted, may be {@code null}
628	     * @return the normalized address, or an empty string when none was supplied
629	     */
630	    private String normalizeAddress(String address) {
631	        if (address == null) {
632	            return "";
633	        }
634	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
635	        if (collapsed.isEmpty()) {
636	            return "";
637	        }
638	        String[] tokens = collapsed.split(" ");
639	        StringBuilder normalized = new StringBuilder(collapsed.length());
640	        for (int i = 0; i < tokens.length; i++) {
641	            if (i > 0) {
642	                normalized.append(' ');
643	            }
644	            normalized.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
645	        }
646	        return normalized.toString();
647	    }
648	
649	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
650	    @Override
651	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
652	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
653	        if (currentOwner == null) {
654	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
655	        }
656	        currentOwner.setAddress(ownerFieldsDto.getAddress());
657	        currentOwner.setCity(ownerFieldsDto.getCity());
658	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
659	        currentOwner.setLastName(ownerFieldsDto.getLastName());
660	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
661	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
662	        this.clinicService.saveOwner(currentOwner);
663	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
664	    }
665	
666	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
667	    @Transactional
668	    @Override
669	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
670	        Owner owner = this.clinicService.findOwnerById(ownerId);
671	        if (owner == null) {
672	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
673	        }
674	        this.clinicService.deleteOwner(owner);
675	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
676	    }
677	
678	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
679	    @Override
680	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
681	        Owner owner = this.clinicService.findOwnerById(ownerId);
682	        if (owner == null) {
683	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
684	        }
685	        HttpHeaders headers = new HttpHeaders();
686	        Pet pet = petMapper.toPet(petFieldsDto);
687	        owner.setId(ownerId);
688	        pet.setOwner(owner);
689	        pet.getType().setName(null);
690	        this.clinicService.savePet(pet);
691	        PetDto petDto = petMapper.toPetDto(pet);
692	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
693	            .buildAndExpand(pet.getId()).toUri());
694	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
695	    }
696	
697	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
698	    @Override
699	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
700	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
701	        if (currentOwner != null) {
702	            Pet currentPet = this.clinicService.findPetById(petId);
703	            if (currentPet != null) {
704	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
705	                currentPet.setName(petFieldsDto.getName());
706	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
707	                this.clinicService.savePet(currentPet);
708	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
709	            }
710	        }
711	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
712	    }
713	
714	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
715	    @Override
716	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
717	        HttpHeaders headers = new HttpHeaders();
718	        Visit visit = visitMapper.toVisit(visitFieldsDto);
719	        Pet pet = new Pet();
720	        pet.setId(petId);
721	        visit.setPet(pet);
722	        this.clinicService.saveVisit(visit);
723	        VisitDto visitDto = visitMapper.toVisitDto(visit);
724	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
725	            .buildAndExpand(visit.getId()).toUri());
726	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
727	    }
728	
729	
730	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
731	    @Override
732	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
733	        Owner owner = this.clinicService.findOwnerById(ownerId);
734	        if (owner != null) {
735	            Pet pet = owner.getPet(petId);
736	            if (pet != null) {
737	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
738	            }
739	        }
740	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
741	    }
742	}
